APELO = {'fascismo', 'nazismo', 'integralismo', 'militarismo-autoritario', 'marxismo-leninismo', 'maoismo'}
A = {
'liberalismo-classico': (['Limitar o poder protege contra abusos de qualquer governo.', 'Liberdade de expressão e de imprensa são a base para corrigir erros.', 'Mercados coordenam informação dispersa melhor do que muitos planos centrais.'], ['Defendeu direitos universais enquanto muitos de seus autores aceitavam escravidão, colonialismo ou voto só para proprietários.', 'Quer um Estado pequeno, mas depende dele para garantir contratos e propriedade.', 'Liberdade formal pode pouco para quem não tem meios de exercê-la.']),
'neoliberalismo': (['Controlar a inflação protege sobretudo os mais pobres.', 'Concorrência e abertura podem baixar preços e reduzir privilégios de setores protegidos.', 'Gastar sem limite costuma cobrar a conta depois.'], ['Fala em menos Estado, mas precisa de um Estado forte para impor reformas, e no Chile conviveu com a ditadura.', 'Defende concorrência e já gerou monopólios privados por meio de privatizações.', 'Empresas pró-mercado pedem socorro público nas crises, como em 2008.']),
'social-liberalismo': (['Oportunidade real exige educação e saúde.', 'Combina proteção aos direitos e correção de falhas de mercado.', 'Costuma ter bons resultados nos países que combinam mercado e proteção social.'], ['Quanto mais redistribui, mais limita a liberdade econômica que diz prezar.', 'Fala em igualdade de oportunidade, mas heranças e redes de contato seguem pesando.']),
'libertarianismo': (['Toda coerção precisa de justificativa: o ônus é de quem quer limitar.', 'Alerta para os riscos de concentrar poder e para governos que erram.', 'Defende coerentemente liberdades pessoais, como de consumo e expressão.'], ['Protege a propriedade atual sem resolver como ela foi obtida, muitas vezes à força.', 'Rejeita imposto, mas precisa financiar polícia e justiça.', 'Defende liberdade e aceita contratos em que quem não tem alternativa fica sem escolha real.']),
'anarcocapitalismo': (['Questiona um ponto que muitos aceitam sem pensar: por que o Estado pode o que ninguém mais pode?', 'Mostra que serviços considerados só estatais podem ter alternativas.', 'Lembra que Estados já cometeram os maiores massacres da história.'], ['Sem Estado, quem garante a propriedade? A agência mais forte pode virar um Estado de fato.', 'Rejeita a coerção estatal, mas aceita o poder de quem é dono de tudo em volta.', 'Defende contratos voluntários, mas os mais pobres teriam pouco poder de escolha.']),
'conservadorismo': (['Mudanças sociais têm efeitos não previstos.', 'Instituições acumulam conhecimento que ninguém planejou.', 'Comunidade, família e religião dão sentido e apoio a muita gente.'], ['Defende a tradição, mas as tradições são muitas. Quem decide qual preservar?', 'Hoje conserva conquistas que ontem combateu, como o voto feminino.', 'Apoia o mercado, que dissolve muitos dos costumes que quer conservar.']),
'liberal-conservadorismo': (['Busca unir responsabilidade individual e laços sociais.', 'Mercado funciona melhor com confiança e normas compartilhadas.'], ['Quer liberdade na economia e regula escolhas pessoais.', 'Desconfia do Estado, mas pede a ele que imponha moral e aumente a repressão.', 'Defende tradição e aceita o consumo que a transforma.']),
'democracia-crista': (['Mostrou que mercado e solidariedade podem ser combinados.', 'Valoriza família e comunidades locais.', 'Ajudou a reconstruir democracias após 1945.'], ['Baseia-se em doutrina religiosa, mas governa quem não crê.', 'Fala em dignidade da pessoa e pode restringir escolhas sobre o próprio corpo.']),
'reacionarismo': (['Aponta perdas reais da modernidade, como isolamento e falta de sentido.', 'Lembra que progresso técnico não é progresso moral automático.'], ['Quer voltar a um passado idealizado, que não existiu para todos.', 'Usa redes sociais e mercado de massa para combater a modernidade.', 'Rejeita a autoridade dos especialistas, mas pede obediência a outras autoridades.']),
'monarquismo': (['Um chefe de Estado fora da disputa eleitoral pode dar estabilidade.', 'Monarquias constitucionais estão entre as democracias com melhores índices.'], ['O cargo mais alto é herdado em uma sociedade que diz premiar o mérito.', 'O monarca “acima da política” tem riqueza e influência privilegiadas.']),
'populismo': (['Dá voz a excluídos e denuncia elites que de fato se afastam do povo.', 'Mostra quando as instituições deixam de representar as pessoas.'], ['Fala em nome de todo o povo, mas exclui quem discorda.', 'Ataca elites e cria uma nova em torno do líder.', 'Promete devolver o poder ao povo e concentra poder em uma pessoa.']),
'nacionalismo': (['Identidade comum pode sustentar solidariedade e impostos.', 'Ajudou povos colonizados a se libertar.', 'Soberania protege decisões democráticas.'], ['Toda nação é construída, mas é tratada como natural e eterna.', 'Quer autodeterminação para a própria nação e nem sempre para as vizinhas.', 'Problemas como o clima não respeitam fronteiras.']),
'fascismo': (['Prometeu ordem após crises e humilhação nacional.', 'Oferecia pertencimento e um inimigo a quem culpar.', 'Atraiu quem temia o comunismo e o caos econômico.'], ['Prometeu grandeza nacional e levou o país à destruição.', 'Falava em unir o povo e perseguia parte dele.', 'Atacava elites e fez acordos com elas.']),
'nazismo': (['Explorou a crise econômica, o ressentimento após 1918 e o antissemitismo antigo.', 'Oferecia emprego, ordem e um bode expiatório.', 'Usou propaganda em massa de forma inédita.'], ['Falava em superioridade racial sem nenhuma base científica.', 'Usou “socialista” no nome e perseguiu socialistas.', 'Prometeu mil anos de Reich e deixou o país em ruínas.']),
'integralismo': (['Atraiu quem buscava identidade nacional e ordem nos anos 1930.', 'Tinha forte mobilização de classe média e de setores religiosos.'], ['Era nacionalista, mas copiava modelos europeus.', 'Dizia defender a família e aceitava a violência política.']),
'militarismo-autoritario': (['Prometeu ordem em momentos de crise e medo do comunismo.', 'Teve apoio de parte da sociedade, e alguns períodos com forte crescimento.'], ['Tomou o poder dizendo salvar a democracia, e a suprimiu.', 'Prometeu acabar com a corrupção e escondeu a sua sob censura.', 'Falava em união nacional e torturava cidadãos.']),
'centrismo': (['Aprende com os dois lados e procura o que funciona.', 'Costuma dar estabilidade e permitir acordos.'], ['O centro muda conforme os extremos: o meio-termo pode ser só uma posição do momento.', 'Fala em soluções técnicas, mas toda escolha técnica carrega valores.', 'A moderação pode virar omissão diante de injustiças graves.']),
'social-democracia': (['Países que a adotaram estão entre os de melhores índices de vida.', 'Combina mercado, democracia e proteção social.', 'Mostrou que se pode reduzir a desigualdade sem revolução.'], ['Depende do crescimento capitalista que quer limitar.', 'Saída de capital e competição global pressionam seu financiamento.', 'Boa parte do bem-estar foi construída em países ricos, com vantagens na economia global.']),
'trabalhismo': (['Direitos trabalhistas mudaram a vida de milhões.', 'Valoriza educação pública integral, como nos CIEPs.'], ['Nasceu no Estado Novo: direitos dados por uma ditadura, com sindicatos atrelados ao governo.', 'Protege quem tem carteira assinada e pouco alcança os informais.', 'Fala em emancipação e cria dependência de líderes.']),
'desenvolvimentismo': (['Coreia do Sul e China mostram que o Estado pode acelerar a industrialização.', 'Países não ficam ricos só exportando matéria-prima.'], ['Protege empresas para que elas fiquem competitivas, e muitas nunca ficam.', 'Quer autonomia nacional e depende de crédito e tecnologia externos.', 'Já conviveu tanto com democracias quanto com ditaduras, sem resolver a desigualdade.']),
'socialismo-democratico': (['Lembra que democracia também poderia valer no trabalho.', 'Rejeita o autoritarismo em nome da igualdade.', 'Questiona o poder econômico sobre a política.'], ['Promete mudança profunda, enquanto a alternância de governo poderia desfazê-la a cada eleição.', 'Precisa do apoio da maioria para medidas que causam reação forte.', 'Poucos casos concretos: não há um modelo testado por muito tempo.']),
'marxismo': (['Mostra como classe e poder econômico moldam a política.', 'Antecipou concentração de capital e crises recorrentes.', 'Deu ferramentas a movimentos operários, que conquistaram direitos.'], ['Promete o fim do Estado, mas as tentativas o fortaleceram.', 'Fala em emancipação, e os regimes marxistas suprimiram os trabalhadores que diziam representar.', 'Previu revolução nos países industriais, e ela veio em países agrários.', 'Critica o determinismo, mas tem leituras muito deterministas da história.']),
'comunismo': (['O ideal de distribuir segundo a necessidade tem forte apelo moral.', 'Alguns regimes ampliaram alfabetização e saúde rapidamente.', 'Lembra o custo humano da desigualdade extrema.'], ['Prometeu o fim das classes e criou uma nova elite partidária.', 'Prometeu o fim do Estado e criou alguns dos mais fortes já vistos.', 'Falava em libertar trabalhadores e proibiu sindicatos independentes e greves.']),
'marxismo-leninismo': (['Prometeu tirar países agrários da miséria e da humilhação.', 'Industrializou a URSS em pouco tempo, a um custo humano enorme.', 'Atraiu quem combatia o czarismo e, depois, o nazismo.'], ['Dizia dar o poder aos sovietes e o concentrou no partido.', 'Usou o terror contra operários e camponeses em nome deles.', 'Partido “de vanguarda” decide pelos outros, em nome da libertação.']),
'trotskismo': (['Fez uma crítica importante à burocracia e ao terror de Stálin.', 'Lembrou o caráter internacional do capitalismo.'], ['Critica o autoritarismo, mas Trótski reprimiu Kronstadt e defendeu partido único.', 'Fala em unidade dos trabalhadores e sofre muitos rachas internos.']),
'maoismo': (['Deu protagonismo a camponeses, antes ignorados por muitos marxistas.', 'Atraiu movimentos anticoloniais no Terceiro Mundo.'], ['Fala em massas contra burocratas e criou o culto a um líder único.', 'Prometeu superar a fome e causou uma das maiores da história.', 'A China que se diz herdeira adotou mercado e bilionários.']),
'ecossocialismo': (['Leva a sério os limites físicos do planeta.', 'Liga a crise ecológica à desigualdade.', 'Questiona o crescimento como único objetivo.'], ['Regimes socialistas também tiveram desastres ambientais graves, como no mar de Aral.', 'Quer limitar o consumo e prometer vida melhor aos mais pobres ao mesmo tempo.', 'A transição requer tecnologia hoje desenvolvida sobretudo por mercados.']),
'teologia-da-libertacao': (['Colocou os pobres no centro da fé e da política.', 'Teve papel real contra ditaduras e em movimentos populares.'], ['Quer unir fé e método marxista, cuja origem é crítica à religião.', 'Muitos pobres preferiram igrejas pentecostais com outra mensagem.']),
'anarquismo': (['Toda hierarquia deve se justificar: uma regra útil para qualquer poder.', 'Mostrou o valor da ajuda mútua e da autogestão.', 'Previu que uma ditadura socialista viraria um novo opressor.'], ['Quer abolir o poder, mas toda decisão coletiva cria alguma pressão sobre quem discorda.', 'Sem coerção, como conter quem usa a força?', 'Rejeita líderes e, na prática, surgem lideranças informais.']),
'anarcocomunismo': (['Mostra que a cooperação é tão natural quanto a competição, como argumentou Kropotkin.', 'Pequenas comunidades de fato funcionam sem dinheiro.'], ['Sem preços nem autoridade, como decidir o que produzir em grande escala?', 'A liberdade da comuna pode oprimir quem pensa diferente.', 'Precisou se defender com milícias, uma forma de poder armado.']),
'anarcossindicalismo': (['Mostrou a força da greve e da organização direta.', 'Experiências de autogestão na Espanha funcionaram por algum tempo.'], ['Um grande sindicato pode virar uma burocracia.', 'Dá poder aos que trabalham e deixa fora desempregados, idosos e crianças.']),
'mutualismo': (['Cooperativas reais existem e prosperam, como Mondragón.', 'Mostra que mercado e capitalismo não são sinônimos.'], ['Sem acumulação, como financiar projetos grandes?', 'Quer mercado livre e proíbe formas de lucro que o mercado cria.']),
'ambientalismo': (['A ciência do clima é sólida, e os danos são reais.', 'Prevenir costuma ser mais barato que remediar.', 'Inclui as gerações futuras na conta.'], ['Pede mudança global e pesa mais sobre os pobres, se mal desenhado.', 'Muitos se opõem à energia nuclear, que tem baixa emissão de carbono.', 'Protege a natureza e às vezes ignora o sofrimento de animais individuais.']),
'feminismo': (['Conquistou voto, trabalho e leis contra a violência.', 'Mostrou desigualdades que passavam por naturais.'], ['Correntes divergem até sobre pontos centrais, como trabalho sexual e pornografia.', 'Por muito tempo, falou sobretudo por mulheres brancas e de classe média, como apontou o feminismo negro.']),
'comunitarismo': (['Pessoas não são átomos: relações formam quem somos.', 'Comunidades cuidam do que mercado e Estado não alcançam.'], ['Valoriza a comunidade, mas quem escolhe a sua não é livre para rejeitá-la por inteiro.', 'Defende valores locais, mesmo quando eles ferem membros mais fracos.']),
'cosmopolitismo': (['Nascer em um lugar é sorte, não mérito.', 'Clima e pandemias exigem cooperação global.'], ['Defende direitos globais sem haver instituições globais capazes de garanti-los.', 'Governança distante pode ser menos democrática.']),
'senciocracia': (['A dor não depende da espécie: o critério moral é coerente, e coincide com o que a ciência admite sobre a consciência animal.', 'Quem é afetado por uma decisão deveria ter seus interesses considerados nela.', 'Crianças e futuros seres já são representados por outros: a ideia não é tão estranha.', 'Pode dar peso político ao sofrimento que hoje não aparece nas eleições.'], ['Fala em “governo” de seres que não podem votar nem deliberar: quem fala por eles?', 'Humanos ainda decidiriam tudo, com risco de usar os animais a favor das próprias causas.', 'Como pesar interesses entre números enormes de seres, como insetos, e poucos humanos?', 'Vai além do veganismo: incluir animais na natureza e possíveis sistemas digitais sencientes amplia muito o que precisaria ser protegido, e como fazê-lo.', 'É pouco testada e precisa de maioria humana para existir.']),
}
SENCIOCRACIA = dict(s='senciocracia', n='Sencientismo e senciocracia', f='Temas transversais', x=-12, y=-78, r='Colocar os seres sencientes no centro da política, e um governo que os represente e proteja.', i='Sencientismo, também descrito como senciocentrismo ou ética baseada na senciência, é a visão de que todos os que podem sentir contam: a capacidade de ter experiências boas e ruins é o critério, e a consideração não para na espécie. Aplicado à política, coloca humanos, animais não humanos e outros possíveis seres sencientes no centro das decisões. Senciocracia (em inglês, sentiocracy) é a forma de governo que decorre disso, com instituições que representem e protejam esses seres. O sencientismo diz quem conta; a senciocracia pergunta como o sistema político deveria agir a partir disso. Ela pode se combinar com diferentes teorias éticas, como o consequencialismo ou as teorias de direitos. É uma ideia ainda em construção, sem modelo único de funcionamento.', e='Com instituições que protejam e representem quem não pode votar.', m='Questiona setores baseados em sofrimento, como a pecuária industrial.', d='Proteção política a todos os seres sencientes, independentemente de lugar ou tempo.', q='Sem distinção de espécie: busca o melhor para cada indivíduo.', p='Na base moral: Jeremy Bentham, Peter Singer, Tom Regan, Oscar Horta e Luciano Carlos Cunha. Na proposta política: Sue Donaldson e Will Kymlicka (Zoopolis), Alasdair Cochrane (Sentientist Politics), Magnus Vinding (Reasoned Politics), John Adenitire e Raffael Fasel (Animals and the Constitution), Lara de Mendonça André.', h='A base moral aparece em Bentham (1789), e o termo sencientismo foi usado por John Rodman em 1977; hoje se apoia em declarações científicas sobre consciência animal. Nenhum país adotou o sistema político. Há passos parciais, como leis que reconhecem animais como seres sencientes.', b='Discussão ainda pequena, com divulgação em português em sites como a Vegpedia. O Brasil tem leis contra maus-tratos e uma comunidade ativa de defesa animal.', pa=[], fi=[], c='Críticos dizem que a política pressupõe deliberação e deveres, que animais não têm. Jorge Valadez questiona se capacidades tão variadas de senciência podem fundar igualdade moral. Há incerteza sobre onde termina a senciência, e forte resistência cultural e econômica. Veja a lição sobre inclusão moral e sencientismo.', w='Sencientismo', fx=[('Vegpedia: Senciocracia', 'https://vegpedia.com/senciocracia/'), ('Sentientist Politics', 'https://academic.oup.com/book/5971'), ('The Relevance of Sentience', 'https://repositorium.sdum.uminho.pt/bitstream/1822/64187/2/Lara%20de%20Mendon%C3%A7a%20Andr%C3%A9.pdf'), ('Zoopolis', 'https://www.google.com/search?tbm=bks&q=Zoopolis+Donaldson+Kymlicka'), ('Crítica a Sentientist Politics', 'https://journals.lub.lu.se/pa/article/view/23522')], wl='Wikipédia: Sencientismo')
